class Solution {

    public int minEatingSpeed(int[] piles, int h) {
        int lo = 1,
            hi = 0;
        for (int p : piles) hi = Math.max(hi, p);
        int ans = hi;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (hoursNeeded(piles, mid) <= h) {
                ans = mid; // feasible, try a smaller speed
                hi = mid - 1;
            } else {
                lo = mid + 1; // too slow
            }
        }
        return ans;
    }

    private long hoursNeeded(int[] piles, int k) {
        long hours = 0; // can exceed int when k is small
        for (int p : piles) hours += (p + k - 1) / k; // ceil(p / k)
        return hours;
    }
}

