    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int m = nums1.length,
            n = nums2.length,
            total = m + n;
        int i = 0,
            j = 0,
            prev = 0,
            curr = 0;
        for (int count = 0; count <= total / 2; count++) {
            prev = curr;
            // take from nums1 if nums2 is exhausted or nums1 has the smaller head
            if (i < m && (j >= n || nums1[i] <= nums2[j])) curr = nums1[
                i++
            ];
            else curr = nums2[j++];
        }
        if (total % 2 == 1) return curr;
        return (prev + (double) curr) / 2.0;
    }
}

