class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1); // search the smaller
        one
        int m = nums1.length, n = nums2.length;
        int half = (m + n + 1) / 2;               // size of the left half
        int lo = 0, hi = m;
        while (lo <= hi) {
            int cut1 = lo + (hi - lo) / 2;     // elements taken from nums1
            int cut2 = half - cut1;            // elements taken from nums2
            int L1 = cut1 == 0 ? Integer.MIN_VALUE : nums1[cut1 - 1];
            int R1 = cut1 == m ? Integer.MAX_VALUE : nums1[cut1];
            int L2 = cut2 == 0 ? Integer.MIN_VALUE : nums2[cut2 - 1];
            int R2 = cut2 == n ? Integer.MAX_VALUE : nums2[cut2];
            if (L1 <= R2 && L2 <= R1) {
                if ((m + n) % 2 == 1) return Math.max(L1, L2);
                return (Math.max(L1, L2) + (double) Math.min(R1, R2)) / 2.0;
            } else if (L1 > R2) {
                hi = cut1 - 1;                 // took too many from nums1
            } else {
                lo = cut1 + 1;                 // took too few from nums1
            }
        }
        return 0.0; // unreachable for valid sorted input
    }
}

