class Solution {

    public int search(int[] nums, int target) {
        int n = nums.length,
            lo = 0,
            hi = n - 1;
        while (lo < hi) {
            // find index of the minimum
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] > nums[hi]) lo = mid + 1;
            else hi = mid;
        }
        int pivot = lo;
        // choose the sorted run that can contain target
        if (target >= nums[pivot] && target <= nums[n - 1]) return bs(
            nums,
            pivot,
            n - 1,
            target
        );
        return bs(nums, 0, pivot - 1, target);
    }

    private int bs(int[] a, int lo, int hi, int target) {
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) return mid;
            if (a[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }
}

