class TimeMap {

    private final Map<String, List<Pair>> map = new HashMap<>();

    private static class Pair {

        int time;
        String value;

        Pair(int t, String v) {
            time = t;
            value = v;
        }
    }

    public TimeMap() {}

    public void set(String key, String value, int timestamp) {
        map.computeIfAbsent(key, k -> new ArrayList<>()).add(
            new Pair(timestamp, value)
        );
    }

    public String get(String key, int timestamp) {
        List<Pair> list = map.get(key);
        if (list == null) return "";
        for (int i = list.size() - 1; i >= 0; i--) {
            // newest first
            if (list.get(i).time <= timestamp) return list.get(i).value;
        }
        return "";
    }
}

