        let lo = 0,
            hi = n - 1;
        while (lo <= hi) {
            const mid = lo + ((hi - lo) >> 1);
            if (row[mid] === target) return true;
            if (row[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return false;
};

