class Solution {

    public int NthRoot(int n, int m) {
        long lo = 1,
            hi = m;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            int c = compare(mid, n, m);
            if (c == 1) return (int) mid;
            if (c == 0) lo = mid + 1;
            // mid^n < m
            else hi = mid - 1; // mid^n > m
        }
        return -1;
    }

    // 0: mid^n < m, 1: mid^n == m, 2: mid^n > m (never computes past m, so no overflow)
    private int compare(long mid, int n, int m) {
        long p = 1;
        for (int i = 0; i < n; i++) {
            p *= mid;
            if (p > m) return 2;
        }
        return p == m ? 1 : 0;
    }
}

