    public static int aggressiveCows(int[] stalls, int k) {
        Arrays.sort(stalls);
        int n = stalls.length,
            best = 0;
        for (int d = 1; d <= stalls[n - 1] - stalls[0]; d++) {
            if (canPlace(stalls, k, d)) best = d;
            else break; // larger d will fail too
        }
        return best;
    }

    static boolean canPlace(int[] stalls, int k, int d) {
        int count = 1,
            last = stalls[0]; // first cow in first stall
        for (int i = 1; i < stalls.length; i++) {
            if (stalls[i] - last >= d) {
                count++;

                last = stalls[i];
                if (count >= k) return true;
            }
        }
        return count >= k;
    }
}

