class Solution {

    public static int findPages(int[] arr, int k) {
        int n = arr.length;
        if (k > n) return -1;
        int max = 0;
        long sum = 0; // long: total pages may exceed int
        for (int x : arr) {
            max = Math.max(max, x);
            sum += x;
        }
        for (long limit = max; limit <= sum; limit++) {
            if (studentsNeeded(arr, limit) <= k) return (int) limit;
        }
        return -1;
    }

    static int studentsNeeded(int[] arr, long limit) {
        int students = 1;
        long pages = 0;

        for (int x : arr) {
            if (pages + x > limit) {
                // start a new student
                students++;
                pages = x;
            } else {
                pages += x;
            }
        }
        return students;
    }
}

