class Solution {

    int median(int[][] mat) {
        int R = mat.length,
            C = mat[0].length;
        int lo = Integer.MAX_VALUE,
            hi = Integer.MIN_VALUE;
        for (int[] row : mat) {
            lo = Math.min(lo, row[0]);
            hi = Math.max(hi, row[C - 1]);
        }
        int half = (R * C) / 2,
            ans = lo;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int count = 0;
            for (int[] row : mat) count += upperBound(row, mid); // elements <= mid
            if (count > half) {
                ans = mid; // mid has more than half at or below it
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return ans;
    }

    // number of elements in sorted row that are <= x
    private int upperBound(int[] row, int x) {
        int lo = 0,
            hi = row.length - 1,
            ans = row.length;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (row[mid] > x) {
                ans = mid;
                hi = mid - 1;
            } else lo = mid + 1;
        }
        return ans;
    }
}

