class Solution {

    public int kthElement(int[] a, int[] b, int k) {
        if (a.length > b.length) return kthElement(b, a, k); // search the smaller array
        int m = a.length,
            n = b.length;
        int lo = Math.max(0, k - n),
            hi = Math.min(k, m); // valid range for cut1
        while (lo <= hi) {
            int cut1 = lo + (hi - lo) / 2;
            int cut2 = k - cut1;
            int L1 = cut1 == 0 ? Integer.MIN_VALUE : a[cut1 - 1];

            int R1 = cut1 == m ? Integer.MAX_VALUE : a[cut1];
            int L2 = cut2 == 0 ? Integer.MIN_VALUE : b[cut2 - 1];
            int R2 = cut2 == n ? Integer.MAX_VALUE : b[cut2];
            if (L1 <= R2 && L2 <= R1) return Math.max(L1, L2); // k-th is the largest on the left
            if (L1 > R2) hi = cut1 - 1;
            // too many from a
            else lo = cut1 + 1; // too few from a
        }
        return -1; // unreachable for valid k
    }
}

